{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create Or Replace table Maplemonk.cc_affiliate_spends_summary as With OrderId_Level_Affiliates as ( select date ,upper(ifnull(brand,\'\')) as brand ,upper(ifnull(region,\'\')) as region ,upper(ifnull(order_currency,\'\')) order_currency ,upper(ifnull(aff_net_name,\'\')) aff_net_name ,order_network ,sum(ifnull(Affiliation_Cost,0)) as Affiliation_Cost from ( select af.order_id, aff_net_name, order_network, order_currency, date, brand, region, safe_divide((ifnull(Affiliation_Cost,0)),count(1) over(partition by ifnull(af.order_id,0),ifnull(aff_net_name,\'\'))) Affiliation_Cost from ( select aff_net_name ,order_network ,LAST_DAY(DATE(cast(order_year as int64), cast(order_Month as int64), 1)) as date ,order_id ,order_currency ,Sum(ifnull(order_commission ,0)) + sum(ifnull(network_cost,0)) as Affiliation_Cost from ( select s.*,aff_net_name,current_status,decline_reason from cc_comfort_db.affiliates_network_sales_track_data s left join ( select distinct aff_net_id,aff_net_name from cc_comfort_db.affiliates_network )m on s.order_network = m.aff_net_id left join ( select order_id,decline_reason from cc_comfort_db.order_processing qualify ROW_NUMBER() over(partition by (ifnull(order_id,0)) order by 1) = 1 )op on cast(op.order_id as int64) = cast(s.order_id as int64) left join ( select order_id,current_status from cc_comfort_db.order_master qualify ROW_NUMBER() over(partition by (ifnull(order_id,0)) order by 1) = 1 )om on cast(om.order_id as int64) = cast(s.order_id as int64) ) where (not(ifnull(current_status,1) in (0,4,25)) or lower(ifnull(decline_reason,\'\')) != \'test order\' ) group by 1,2,3,4,5 ) af left join ( select distinct order_id, brand, region from Maplemonk.cc_sales_consolidated ) sc on ifnull(cast(af.order_id as string),\'\') = ifnull(cast(sc.order_id as string),\'\') ) group by 1,2,3,4,5,6 ), pre_final_result as ( select date, brand, region, aff_net_name, order_network, sum(ifnull(mc.Affiliation_Cost,0)/ifnull(rh.er_exchange_rate,1)) as Spend from OrderId_Level_Affiliates mc left join `cc_comfort_db.exchange_rate_history` rh on cast(rh.er_date as date) = cast(mc.date as date) and upper(trim(mc.order_currency)) = upper(trim(rh.er_currency_name)) group by 1,2,3,4,5 ), Final_Result as ( select fi.* ,ncd.cost_value ,safe_divide(Spend,sum(Spend) over(partition by date,ifnull(aff_net_name,\'\'),order_network)) share ,case when ifnull(month_flag,0)=1 then ifnull(cost_value,0) * (safe_divide(Spend,sum(Spend) over(partition by date,ifnull(aff_net_name,\'\'),order_network))) else Spend end as affiliate_spend from pre_final_result fi left join ( select network_id ,LAST_DAY(DATE(cast(year_number as int64), cast(financial_month as int64), 1)) AS last_day_of_month ,sum(ifnull(cost_value,0)) cost_value ,1 as month_flag from cc_comfort_db.amr_network_cost_data group by 1,2 )ncd on fi.date = ncd.last_day_of_month and fi.order_network = ncd.network_id ) ,parsed_dates AS ( SELECT DATE_TRUNC(date, MONTH) AS start_date, case when last_day(current_date) = date then current_date else date end AS End_Date, brand, region, aff_net_name, order_network, affiliate_spend FROM final_result ), date_series AS ( SELECT start_date, End_Date, brand, region, aff_net_name, order_network, affiliate_spend, DATE_ADD(Start_Date, INTERVAL day_offset DAY) AS daily_date FROM parsed_dates, UNNEST(GENERATE_ARRAY(0, DATE_DIFF(End_Date, Start_Date, DAY))) AS day_offset ) SELECT daily_date AS Date, affiliate_spend / (DATE_DIFF(End_Date, Start_Date, DAY) + 1) AS affiliate_spend, brand, region, aff_net_name, order_network FROM date_series ORDER BY Date ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            